import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_packages(data):
    result = {}
    for project in data.get('projects', []):
        pname = project['path'].split('/')[-1]
        pkgs = {}
        for fw in project.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], fw['framework'])
                pkgs[key] = pkg['resolvedVersion']
        result[pname] = pkgs
    return result

b = get_packages(baseline)
a = get_packages(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes.append(f'{proj}: {key[0]} ({key[1]}): {bv} -> {av}')

if changes:
    print('VERSION CHANGES:')
    for c in changes: print(f'  {c}')
else:
    print('No version changes - conversion is version-neutral for unchanged packages')

# Check for expected alignment changes
print()
print('Expected alignments (conflicts resolved to highest):')
for proj in sorted(b.keys()):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(bp.keys()):
        if bp[key] != ap.get(key, bp[key]):
            print(f'  {proj}: {key[0]} ({key[1]}): {bp[key]} -> {ap[key]}')
